/* Generated by ADS from fonts.css and base.css or assets.preloadFonts: the fonts the first text uses. `ads assets` and the
   showcase and MCP server rewrite it; do not edit it. Call preloadFonts() in the app entry before
   the first render, or put fontPreloadTags() or fontPreloadHeader() in the page from a build step. */
import font0 from "../assets/fonts/Geist-Variable.woff2";

export const fontPreloads: readonly { readonly href: string; readonly type: string }[] = [
  { href: font0, type: "font/woff2" },
];

/** The same list for a build step or prerender: <link> tags for the page's HTML. */
export function fontPreloadTags(): string {
  return fontPreloads.map(({ href, type }) => `<link rel="preload" href="${href}" as="font" type="${type}" crossorigin="anonymous">`).join("\n");
}

/** The same list as a Link header value. */
export function fontPreloadHeader(): string {
  return fontPreloads.map(({ href, type }) => `<${href}>; rel=preload; as=font; type="${type}"; crossorigin=anonymous`).join(", ");
}

/** Adds one preload link per font. The crossorigin attribute matches how browsers fetch fonts. */
export function preloadFonts(): void {
  for (const { href, type } of fontPreloads) {
    const link = document.createElement("link");
    link.rel = "preload"; link.as = "font"; link.type = type; link.href = href; link.crossOrigin = "anonymous";
    document.head.append(link);
  }
}
